                module MapAuxiliaryCodes
                ; Документация [общие коды и смежная граница](../../../Docs/AuxiliaryMapPoints.md)
                assert $ == #99A3
                ; ActiveCode и CompletionCode совпадают с ячейками состояния миссии
                ; Unknown02..Unknown10 сохранены, карта читает их как числовые управляющие коды
                ; Все байтовые значения отдельного кода [проверка границы](../../../Docs/AuxiliaryMapPoints.md#полный-байтовый-домен-отдельного-кода)
State:          FMapMarkerCodes {
                    #00,                                                        ; ActiveCode, состояние миссии и первый код карты
                    #00,                                                        ; CompletionCode, код повторной награды и второй код карты
                    #01,                                                        ; Unknown02, код для Key02, глобальное назначение не установлено
                    #01,                                                        ; Unknown03, код для Key03, глобальное назначение не установлено
                    #01,                                                        ; Unknown04, код для Key04, глобальное назначение не установлено
                    #01,                                                        ; Unknown05, код для Key05, глобальное назначение не установлено
                    #01,                                                        ; Unknown06, код для Key06, глобальное назначение не установлено
                    #01,                                                        ; Unknown07, код для Key07, глобальное назначение не установлено
                    #01,                                                        ; Unknown08, код для Key08, глобальное назначение не установлено
                    #01,                                                        ; Unknown09, код для Key09, глобальное назначение не установлено
                    #00                                                         ; Unknown10, код за десятью физическими ключами, глобальное назначение не установлено
                }
                ; следующий байт принадлежит InterfaceChoices и служит отрицательной границей исходного снимка
                assert $ == #99AE
                endmodule
